appearances.css:
:host{font-size:9px}
.bar{display:flex;flex-wrap:wrap;gap:4px;align-items:center}
.bar select{flex:1 1 140px;font-size:9px;padding:2px 3px}
.bar button{font-size:9px;padding:2px 6px}
.bar label.choice{margin:0;gap:3px;font-size:9px}
.global{padding:4px 4px 3px;margin:4px 0 0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;border-radius:4px}
.layers{grid-template-columns:repeat(2,minmax(0,1fr));gap:4px;margin:4px 0 0}
.layer{padding:3px 4px 4px;border-radius:4px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:2px 0;align-content:start}
.layer h3{grid-column:1/-1;font-size:9px;margin:0;letter-spacing:.04em}
.layer label.choice{grid-column:1/-1;margin:0;display:block}
.layer label.choice>span{display:none}
.layer label.choice select{width:100%;font-size:8.5px;padding:2px 3px;flex:none}
label.row{display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;margin:0;min-width:0}
label.row>span{order:3;font-size:7.5px;text-align:center;line-height:1.1;letter-spacing:-.02em}
label.row>output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap}
label.row>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
label.row .kn svg{width:100%;height:100%}
.status{display:none}
.layer label.choice:last-child{grid-column:2/-1;align-self:center}
